create table public.exam_results (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,exam_session_id uuid not null references public.exam_sessions(id) on delete restrict,student_id uuid not null references public.students(id) on delete restrict,score numeric(8,2) check(score is null or (score>=0 and score<=100)),status text not null default 'PENDING' check(status in('PENDING','GRADED','PUBLISHED')),graded_at timestamptz,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,exam_session_id,student_id));create index exam_results_tenant_student_idx on public.exam_results(tenant_id,student_id);alter table public.exam_results enable row level security;revoke all on public.exam_results from anon,authenticated;create policy exam_results_select_tenant on public.exam_results for select to authenticated using(tenant_id=public.current_tenant_id());insert into public.permissions(code,name,description) values('exam_results.read','Read exam results','View exam results'),('exam_results.create','Create exam results','Record exam results'),('exam_results.update','Update exam results','Grade exam results'),('exam_results.delete','Delete exam results','Delete exam results') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code like 'exam_results.%' on conflict do nothing;
